import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"55、【豐】 離下震上","description":"子夏易傳 - 55、【豐】 離下震上","frontmatter":{"title":"55、【豐】 離下震上","description":"子夏易傳 - 55、【豐】 離下震上"},"headers":[],"relativePath":"classics/zixia/057.md","filePath":"classics/zixia/057.md"}'),i={name:"classics/zixia/057.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_55、【豐】-離下震上" tabindex="-1">55、【豐】 離下震上 <a class="header-anchor" href="#_55、【豐】-離下震上" aria-label="Permalink to “55、【豐】 離下震上”">​</a></h1><p>卦辭：豐，亨。王假之，勿憂宜日中。</p><p>彖曰：豐，大也。明以動，故豐。王假之，尚大也。勿憂宜日中，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎，況於鬼神乎。</p><p>子夏：夫明者，內含其照也。動而施之，乃豐也。明以時動，物伸其直，得盡其大生長之而遂成也。期盛之矣。豐之道者也，唯尚大而當之，故王能極之也。不失天下之情，則勿憂而旣治矣。日之明盛於中也，王宜照於天下也，則無微而不大也。過於中則憂，大斯盈，盈斯缺矣。大之道也，蓋聖人戒乎其大也。</p><p>象曰：雷電皆至，豐。君子以折獄致刑。</p><p>子夏：雷電皆發，天下文明。盛大之時，明刑以肅民也。君子無所隱避，明以折獄而至用，刑可以勿憂。當日中之宜也。</p><p>初九，遇其配主，雖旬無咎。往有尚。</p><p>象曰：雖旬無咎，過旬災也。</p><p>子夏：豐，尚大也。唯其大者至之以陽，遇四務同而相配彼，俟之為巳主，相須而待也。明方動進而速有功也。遲而過旬失其動也。災之道也。</p><p>六二，豐其蔀，日中見鬥，往得疑疾，有孚發若，吉。</p><p>象曰：有孚發若，信以發志也。</p><p>子夏：柔之為道，靜退者也。又以居內，不能大其上也。是障其光而暗其明也。往之為王，雖尊而隂也。蓋相發則覆，疑矣，且履正不邪中。考自信於心明，生於內而悟其違時之失，修改其道，無執其，故得其吉也。</p><p>九三，豐其沛，日中見沬，折其右肱，無咎。</p><p>象曰：豐其沛，不可大事也。折其右肱，終不可用也。</p><p>子夏：居於下體之上，而上應焉。自以為有其位，而應其德也。貴賤之等則三曷足以為德乎。豐沛以為光，應幽隂以為德，豈可大事乎。力小任重者，右肱斯折也。右肱斯折不可用也，自致廢矣。誰復加於咎乎。</p><p>九四，豐其蔀，日中見鬥，遇其夷主，吉。</p><p>象曰：豐其蔀，位不當也。日中見鬥，幽不明也。遇其夷主吉，行也。</p><p>子夏：陽以守卑而不能弘其大，以當於時也。是幽其明而暝其晝也。初陽之來，為相發之主，事合志終，得其明動之義，故吉也。</p><p>六五，來章有慶譽吉。</p><p>象曰：六五之吉，有慶也。</p><p>子夏：柔居尊，陽能尚其大，而不以力得，其日中之宜也。天下無所隱諱，無微而不照，則天下歸其章明之德矣。故其慶譽之吉哉。</p><p>上六，豐其屋，蔀其家，闚其戸，闃其無人，三歳不覿，兇。</p><p>象曰：豐其屋，天際翔也。闚其戸，闃其無人，自藏也。</p><p>子夏：極其大過於豐之所也。無道可弘，柔而無鑒也。唯富其室，厚其家，自謂其翔於天際，人莫之見也。自藏也者，雖闚其戸，可得見乎。過明之逺，而動之極，也不覿，以三年矣。兇其至也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
